        case MULTICHAR_CONSTANT('g','z','i','p'):
        case MULTICHAR_CONSTANT(' ','g','z','i'):
            request->flags |= REQUEST_ACCEPT_GZIP;
            break;
        }

        if (!(p = strchr(p, ',')))
            break;
    }
}

